public static void check(Solution solution) {
    assert Arrays.equals(solution.canMakePaliQueries("abcd", new int[]{{0,2,1},{1,3,1}}), new int[]{True, True});
    assert Arrays.equals(solution.canMakePaliQueries("abcdefghijklmnopqrstuvwxyz", new int[]{{0,25,12},{0,25,13},{0,25,14}}), new int[]{False, True, True});
    assert Arrays.equals(solution.canMakePaliQueries("zaz", new int[]{{0,2,1},{0,1,0},{1,2,0}}), new int[]{True, False, False});
    assert Arrays.equals(solution.canMakePaliQueries("abcda", new int[]{{3,3,0},{1,2,0},{0,3,1},{0,3,2},{0,4,1}}), new int[]{True, False, False, True, True});
